  animation: nn-line-fade-in 0.4s ease-out both;
}

@keyframes nn-line-fade-in {
  from {
    opacity: 0;
    transform: translateY(8px);
    filter: blur(2px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
    filter: blur(0);
  }
}

